window.INDEX = [{"id":"button","name":"Button","category":"actions","description":"The standard action control. Exactly one primary button per view; everything else is secondary, ghost or a link.","variants":14,"page":"components/button.html"},{"id":"button-group","name":"Button group","category":"actions","description":"Several controls joined into one object. Two shapes only: a tinted track for choosing one of a set, and a bordered strip for actions that belong together — or, latched, for filters that can be on at once.","variants":15,"page":"components/button-group.html"},{"id":"dropdown","name":"Dropdown menu","category":"actions","description":"A menu of actions anchored to a trigger. Real focus walks the items one tabindex=\"-1\" at a time; destructive items sit last, below a divider.","variants":15,"page":"components/dropdown.html"},{"id":"table","name":"Table","category":"data","description":"Rows of records with a sortable header. The workhorse of every register screen — order lists, GRN lists, ledgers.","variants":13,"page":"components/table.html"},{"id":"data-table","name":"Data table","category":"data","description":"The register screen assembled: a table with a search box, filters, sortable headers, column visibility, row selection, totals and a pager, all running off one array of records.","variants":11,"page":"components/data-table.html"},{"id":"pagination","name":"Pagination","category":"data","description":"Moves through a long register a page at a time, and says where you are in it. The range and the total are the component; the arrows are only what you do about them.","variants":15,"page":"components/pagination.html"},{"id":"stat-card","name":"Stat card","category":"data","description":"One number that matters, with the label above it and the change since the last period below. The tile a dashboard strip is made of, and the answer whenever the data is a single current value rather than a shape.","variants":14,"page":"components/stat-card.html"},{"id":"chart","name":"Chart","category":"data","description":"Chart.js on a canvas, wearing this system's colours. The legend is HTML and doubles as the palette the canvas paints from, so a swatch and the line it names cannot drift apart.","variants":15,"page":"components/chart.html"},{"id":"progress","name":"Progress","category":"data","description":"The determinate wait. A graphite rail filled to the fraction of a known total that is done — receipt against an order, lines closed on a GRN, quantity built against a plan — with the two figures written out beside it.","variants":14,"page":"components/progress.html"},{"id":"empty-state","name":"Empty state","category":"data","description":"What a region shows when it has nothing to draw. Several situations wearing one shape — nothing created yet, nothing matching the query, nothing asked for yet, nothing left to do, nothing this account may see and nothing that loaded — and the whole job of the component is saying which one it is.","variants":14,"page":"components/empty-state.html"},{"id":"skeleton","name":"Skeleton","category":"data","description":"Grey blocks standing in the exact box the content will occupy — same rows, same leading, same column widths — so the first paint of a screen whose layout is already known lands without moving.","variants":15,"page":"components/skeleton.html"},{"id":"marker","name":"Marker","category":"data","description":"The mark that opens a list item — a dot, a number, an icon or a tinted well — drawn as a real element in a box the height of one line, so it holds its place when the item wraps.","variants":14,"page":"components/marker.html"},{"id":"spinner","name":"Spinner","category":"data","description":"The indeterminate wait. A graphite ring that turns while work of unknown length is in flight, and a line of text that says what the work is.","variants":14,"page":"components/spinner.html"},{"id":"timeline","name":"Timeline","category":"data","description":"What happened to one record, in order — the history strip on a purchase order, the audit trail on a vendor master, the QC events on a batch. Each entry is an actor, a verb, a time, and where it matters what the value was before.","variants":15,"page":"components/timeline.html"},{"id":"permission-matrix","name":"Permission matrix","category":"data","description":"A grid of roles down one axis and permissions down the other, with the granted cell as a real checkbox. The screen an admin uses to say who may approve a purchase order over ₹5,00,000.","variants":13,"page":"components/permission-matrix.html"},{"id":"tree-view","name":"Tree view","category":"data","description":"Records that nest, drawn as rows that expand to reveal the rows underneath them. A bill of material exploded into its sub-assemblies, a chart of accounts, a plant broken down to the bin — every row still a record with its own code and its own figures.","variants":14,"page":"components/tree-view.html"},{"id":"log","name":"Log","category":"data","description":"A scrolling, monospace stream of timestamped lines — build output, a job's stdout, a webhook's delivery attempts. It renders what a process said, in the order it said it, and nothing in it is a record the user edits.","variants":16,"page":"components/log.html"},{"id":"alert","name":"Alert","category":"feedback","description":"An inline notice about the page or the record in front of the user. White card, zinc border, and the only colour is the icon.","variants":14,"page":"components/alert.html"},{"id":"toast","name":"Toast","category":"feedback","description":"A short confirmation that an action the user just took has finished, pushed into a live region pinned to the bottom-left and gone a few seconds later. It reports an outcome; it is never where the outcome is recorded.","variants":15,"page":"components/toast.html"},{"id":"alert-dialog","name":"Alert dialog","category":"feedback","description":"A dialog that interrupts to ask one question the user has to answer before anything else happens. Unlike a plain dialog it does not dismiss on a backdrop click, and unlike an in-place confirm it has room for the reason.","variants":11,"page":"components/alert-dialog.html"},{"id":"dialog","name":"Dialog","category":"feedback","description":"A centred, dismissible panel over a dimmed page. Use it to take a handful of fields without leaving the list.","variants":10,"page":"components/dialog.html"},{"id":"sheet","name":"Sheet","category":"feedback","description":"A panel that slides in from the right edge, full height and a fixed width, over a list that stays visible behind it. Where one row of a register is read, amended, or walked one record to the next without giving up your place in the list.","variants":10,"page":"components/sheet.html"},{"id":"drawer","name":"Drawer","category":"feedback","description":"A panel flush to a horizontal edge of the viewport, sized to its content and capped short of the screen. The phone-shaped place to put a short action list, a quick filter, one record being edited, or the tray a multi-select fills.","variants":11,"page":"components/drawer.html"},{"id":"badge","name":"Badge","category":"feedback","description":"A small pill that labels a record — status, tag or count. Every pill is the same graphite shape; a 6px dot carries the colour.","variants":14,"page":"components/badge.html"},{"id":"tooltip","name":"Tooltip","category":"feedback","description":"A short dark bubble that names the control under the pointer or under the keyboard. It carries a label and nothing else — no controls, no facts that are not already somewhere the user can reach without hovering.","variants":14,"page":"components/tooltip.html"},{"id":"hovercard","name":"Hovercard","category":"feedback","description":"A card of record detail that opens under a link on hover or focus, after a deliberate delay, and stays open long enough to be read and clicked.","variants":14,"page":"components/hovercard.html"},{"id":"popover","name":"Popover","category":"feedback","description":"A panel of controls anchored to a button and opened by a click. It holds things you focus and operate — a filter, a column list, a date range, a two-field edit — and the page behind it keeps working.","variants":14,"page":"components/popover.html"},{"id":"avatar","name":"Avatar","category":"feedback","description":"Initials in a circle standing in for a person. Nothing in this system uploads a photograph, so a zinc tint and two letters is the component; where the identity provider hands one over, the photograph is a layer painted on top of the letters.","variants":13,"page":"components/avatar.html"},{"id":"label","name":"Label","category":"forms","description":"The name of a control, bound to it with for and id or by wrapping it. The smallest component here, and the one that is most often drawn rather than connected.","variants":15,"page":"components/label.html"},{"id":"field","name":"Field","category":"forms","description":"Label, control, help text and error in one block. This is the unit every form is built from, and the thing that owns the wiring between the four.","variants":14,"page":"components/field.html"},{"id":"input","name":"Input","category":"forms","description":"Single-line text entry. The border lives on the wrapper, not on the control, so an icon, a unit or a clear button sits inside the focus outline instead of beside it.","variants":14,"page":"components/input.html"},{"id":"input-group","name":"Input group","category":"forms","description":"One text field — or a from and a to — and the things that qualify it: a unit, a currency, a scope select, an action, an answer the server fills in, all inside a single bordered enclosure that draws one focus outline for all of them.","variants":15,"page":"components/input-group.html"},{"id":"select","name":"Select","category":"forms","description":"One answer out of a short fixed list. A real <select>, styled through its wrapper the way an input is, and an Alpine listbox only for the rows an <option> cannot hold.","variants":14,"page":"components/select.html"},{"id":"textarea","name":"Textarea","category":"forms","description":"Multi-line text entry. Same bordered wrapper as the input, a height measured in rows, and a counter when there is a limit worth showing.","variants":13,"page":"components/textarea.html"},{"id":"checkbox","name":"Checkbox","category":"forms","description":"An independent on or off — one flag, a set of options, or the row selection a register's bulk actions run on. A real native box wearing accent-zinc-700.","variants":16,"page":"components/checkbox.html"},{"id":"radio","name":"Radio","category":"forms","description":"One of a set, and exactly one. Real native radios wearing accent-zinc-700, where the shared name is the group and the only way to mean none is an option that says so.","variants":13,"page":"components/radio.html"},{"id":"toggle","name":"Toggle","category":"forms","description":"A setting that takes effect the moment it is touched. A real checkbox carrying role=\"switch\", with the track and the thumb beside it painted by peer-checked utilities.","variants":13,"page":"components/toggle.html"},{"id":"combobox","name":"Combobox","category":"forms","description":"A text box that filters a list of records and commits one of them. The typing is a search; what reaches the server is a hidden input under it.","variants":14,"page":"components/combobox.html"},{"id":"attachment","name":"Attachment","category":"forms","description":"The documents hanging off a record — a drop zone over the list of what is already there. Every file shows its type, size, who attached it and when.","variants":13,"page":"components/attachment.html"},{"id":"calendar","name":"Calendar","category":"forms","description":"A month grid for picking a date or a range. Monday-first, tabular figures, and the same graphite selection the rest of the system uses.","variants":14,"page":"components/calendar.html"},{"id":"questionnaire","name":"Questionnaire","category":"forms","description":"A run of questions answered in order on one page — a QC checklist, a vendor assessment, a safety audit. One fieldset per question, the question text as its legend, and three equal tiles carrying the answer so a column of them can be read at a glance.","variants":14,"page":"components/questionnaire.html"},{"id":"filter-builder","name":"Filter builder","category":"forms","description":"Conditions composed into a query over a register — one row carrying a field, an operator and a value, added and removed until the list on screen is the list somebody asked for. The control a buyer uses to ask for open orders over ₹2,00,000, from three vendors, due before the end of the month.","variants":14,"page":"components/filter-builder.html"},{"id":"container","name":"Container","category":"layout","description":"The measurements every screen in this library is already making: how wide a page is, how far its content sits from the edge of the column, the three vertical spacings, the responsive column grid, and the rules for what may scroll and in which direction. A reference for the box the other layouts sit in, not a screen of its own.","variants":9,"page":"components/container.html"},{"id":"app-shell","name":"App shell","category":"layout","description":"The page skeleton: an icon rail that expands to a labelled sidebar, a topbar carrying the hamburger, breadcrumb, command palette and account menu, and a single scrolling main column. Everything else in the app renders inside the main column.","variants":1,"page":"components/app-shell.html"},{"id":"page-header","name":"Page header","category":"layout","description":"The top block of a page: where it sits in the app, what it is, what state it is in, and what you can do to it. One h1 per page and it lives here.","variants":8,"page":"components/page-header.html"},{"id":"card","name":"Card","category":"layout","description":"A bordered white panel that groups one thing. A header names it, the body holds the content, and an optional footer carries totals or actions.","variants":9,"page":"components/card.html"},{"id":"separator","name":"Separator","category":"layout","description":"The rule that divides content. Almost always a border on the thing beside it rather than an element of its own, and almost always silent to a screen reader.","variants":6,"page":"components/separator.html"},{"id":"carousel","name":"Carousel","category":"layout","description":"A horizontal rail of items that snaps one item at a time. CSS scroll snap does the moving; the arrows and the counter are the only JavaScript.","variants":8,"page":"components/carousel.html"},{"id":"list-detail","name":"List and detail","category":"layout","description":"A queue on the left and the record being worked on beside it. Arrow keys walk the list, Enter opens the record into the detail pane, and only the two panes scroll — the page behind them does not move.","variants":7,"page":"components/list-detail.html"},{"id":"form-page","name":"Form page","category":"layout","description":"The layout a create or edit screen uses: one h1, the fields grouped in cards, a validation summary that links to every field that failed, and Save and Cancel where the user can always reach them.","variants":8,"page":"components/form-page.html"},{"id":"auth-page","name":"Auth page","category":"layout","description":"The signed-out screen: one centred card, the fewest fields that will do, and nothing else on the page. Sign in, the second factor after it, and every screen the user lands on when one of the two fails.","variants":8,"page":"components/auth-page.html"},{"id":"error-page","name":"Error page","category":"layout","description":"The whole screen the user gets when the page could not be produced at all. It says what failed in their own terms, whether anything they did was saved, and gives one way back into an application whose navigation is not on this page.","variants":7,"page":"components/error-page.html"},{"id":"dashboard","name":"Dashboard","category":"layout","description":"The screen a user lands on after signing in: a strip of figures, one plot, and the queues that are actually waiting for them. Every part of it already exists — this entry is the composition and the rules that govern it.","variants":9,"page":"components/dashboard.html"},{"id":"index-page","name":"Index page","category":"layout","description":"The register screen as a whole page: the breadcrumb and the one h1, the saved views, the filter band, the toolbar that becomes a selection toolbar, the table, the pager, and the states the page as a whole can be in.","variants":9,"page":"components/index-page.html"},{"id":"record-page","name":"Record page","category":"layout","description":"The screen for one record: the band that identifies it and says what state it is in, a strip of the figures that matter, and the sections of detail below it — line items, approvals, documents, activity — carrying only the actions the record's current state allows.","variants":9,"page":"components/record-page.html"},{"id":"inbox-page","name":"Approval inbox","category":"layout","description":"The screen an approver lives in: everything waiting on their signature in one queue, the record beside it, and the decision on a rail where the hand already is. Deciding removes the record from the queue and lands the user on the next one without a reload.","variants":10,"page":"components/inbox-page.html"},{"id":"board","name":"Board","category":"layout","description":"Records in columns by the stage they are at, where each column is one stage and moving a card between two of them is a state change on the server. The column header carries the count, and every move can be made from the keyboard.","variants":10,"page":"components/board.html"},{"id":"schedule-page","name":"Schedule page","category":"layout","description":"What is planned and when, drawn with time as the axis: promised deliveries across a month, production against each line, a shift roster. Position carries meaning — further right is later, and a block twice as wide takes twice as long.","variants":10,"page":"components/schedule-page.html"},{"id":"compare-page","name":"Compare page","category":"layout","description":"Several vendors' quotations against one enquiry, side by side, so a buyer can award the order. Line items down, vendors across, rates in the cells and the totals along the bottom — the comparative statement that is attached to the requisition and shown to whoever signs it.","variants":9,"page":"components/compare-page.html"},{"id":"reconcile-page","name":"Reconcile page","category":"layout","description":"Two sets of records that ought to agree, with the difference between them written out as a figure and the controls that make them agree — pairing, explaining and posting. The variance is the content; the rows that already agree are a count.","variants":10,"page":"components/reconcile-page.html"},{"id":"import-page","name":"Import page","category":"layout","description":"The screen that takes a spreadsheet into the system: the file and the rules stated before it is picked, the column mapping, the review of what the system understood, the failures grouped by kind, and the write itself with a report at the end.","variants":9,"page":"components/import-page.html"},{"id":"search-page","name":"Search page","category":"layout","description":"The whole-page answer to a query typed into the global search: the query echoed as the one h1, the results grouped by record type with a count on every group, the facets that narrow them, and the states the page is in when there is nothing to show yet or nothing to show at all.","variants":10,"page":"components/search-page.html"},{"id":"focus-page","name":"Focus page","category":"layout","description":"One task on the whole screen with the application chrome removed: a bag scanned into a GRN at the gate, a bin counted at a rack, a sample passed or failed at the QC bench. Large targets, type one step up, and a scan field that never gives up the keyboard.","variants":9,"page":"components/focus-page.html"},{"id":"settings-page","name":"Settings page","category":"layout","description":"The configuration screen: a permanent nav of sections down one side and the section being changed beside it. One h1 for the whole screen, an h2 per section, and a Save that belongs to the section rather than to the page.","variants":9,"page":"components/settings-page.html"},{"id":"onboarding-page","name":"Onboarding page","category":"layout","description":"The screen that tracks a deployment being configured: every task that has to be finished before a document can be raised, grouped, with what is done, what is blocked and on what, who owns each one, and what the page becomes once it is finished.","variants":9,"page":"components/onboarding-page.html"},{"id":"audit-page","name":"Audit page","category":"layout","description":"The whole system's audit trail as a page: who changed what, when, and what the value was before. Queried across records, actors, fields and dates, grouped by day, newest first, and append-only — nothing on this screen edits anything.","variants":10,"page":"components/audit-page.html"},{"id":"docs-page","name":"Docs page","category":"layout","description":"The manual inside the application: the standard operating procedures, the approval limits, the definitions a screen assumes you already know. The only screen in this library that is mostly prose, so the measure, the heading rhythm and what a link looks like inside a sentence are the component.","variants":10,"page":"components/docs-page.html"},{"id":"document-page","name":"Document page","category":"layout","description":"The record as a sheet of paper: a purchase order, a GST tax invoice, a delivery challan, a goods receipt note. Laid out on A4, printed from the browser, and built so that what comes out of the printer is the same document that was on screen.","variants":9,"page":"components/document-page.html"},{"id":"label-sheet","name":"Label sheet","category":"layout","description":"Labels that come off a printer and get stuck onto things: a bin label on a rack, a batch label on a drum, a pallet tag, a QC hold sticker. Either a grid of them on an A4 sheet of die-cut stock or one at a time on a continuous roll, sized in millimetres because the stock in the printer is.","variants":9,"page":"components/label-sheet.html"},{"id":"portal-page","name":"Portal page","category":"layout","description":"The screens a supplier signs in to: the orders you have placed with them, the acknowledgement, an invoice against a receipt, what has been paid, and their own details. One vendor is the whole application, and the layout is built to make that visible.","variants":9,"page":"components/portal-page.html"},{"id":"share-page","name":"Share page","category":"layout","description":"The one screen a recipient with no account in the system ever reaches: what was shared, who shared it, the file or files to open, and the date the link stops working. No sign-in, one destination, and nothing behind it to navigate to.","variants":2,"page":"components/share-page.html"},{"id":"tabs","name":"Tabs","category":"navigation","description":"Switches between views of the same record without leaving the page. The panel below changes; the row above is a widget, not a menu, and the keyboard has to know the difference.","variants":13,"page":"components/tabs.html"},{"id":"breadcrumbs","name":"Breadcrumbs","category":"navigation","description":"The path from the section root down to the record on screen. The last crumb says where you are and is not a link.","variants":13,"page":"components/breadcrumbs.html"},{"id":"menubar","name":"Menubar","category":"navigation","description":"A row of menus across the top of a document — File, Edit, View — sharing one tab stop and one keyboard model. A desktop-application affordance, and most internal screens should not have one.","variants":14,"page":"components/menubar.html"},{"id":"navigation-menu","name":"Navigation menu","category":"navigation","description":"A horizontal bar of links to places, some of which open a panel of more links. Every item is an anchor, so the browser's own navigation gestures keep working, and aria-current says which one you are on.","variants":14,"page":"components/navigation-menu.html"},{"id":"sidebar","name":"Sidebar","category":"navigation","description":"The primary navigation panel of the console: a header, grouped menus with counts and submenus, and a footer for the signed-in user. It has three forms — a 256px panel, a 68px icon rail, and an off-canvas sheet over the page.","variants":14,"page":"components/sidebar.html"},{"id":"topbar","name":"Topbar","category":"navigation","description":"The application header above the page content: the sidebar trigger, the context you are working in, what you can search and who you are signed in as. A real <header> holding a named <nav>, sticky over the column and out of the way of everything that opens above it.","variants":14,"page":"components/topbar.html"},{"id":"accordion","name":"Accordion","category":"navigation","description":"Sections of content that collapse to their heading. The heading is a button that toggles the panel below it.","variants":10,"page":"components/accordion.html"},{"id":"collapsible","name":"Collapsible","category":"navigation","description":"One trigger and one panel. The standalone disclosure — show more, an advanced section at the foot of a form, a filter bar that folds away.","variants":13,"page":"components/collapsible.html"},{"id":"command-palette","name":"Command palette","category":"navigation","description":"A ⌘K overlay for jumping to a record or firing an action by typing. It is a shortcut over the navigation, never the only route to something.","variants":10,"page":"components/command-palette.html"}];
